.wt {
   display: flex;
   flex-direction: column;
   height: 100%;
   padding: 6px 10px;
   box-sizing: border-box;
   gap: 4px;
}
.wt-head {
   display: flex;
   align-items: center;
   gap: 6px;
   font-weight: bold;
}
.wt-head .mdi {
   color: #9a9a80;
}
.wt-pct {
   margin-left: auto;
   font-size: 0.85em;
   padding: 1px 8px;
   border-radius: 10px;
   background: #8a8a70;
   color: white;
}
.wt-pct.full {
   background: var(--red);
}
.wt-main {
   flex: 1;
   min-height: 0;
   container-type: size;      /* the tank takes the width of the widget, limited by its height */
   display: flex;
   align-items: center;
   justify-content: center;
}

/* the tank: wide and flat, its height by the width (aspect-ratio of the body) */

.wt-tank {
   position: relative;
   width: min(100% - 16px, 340px, (100cqh - 44px) * 2.2);
   display: flex;
   flex-direction: column;
   cursor: pointer;
}
.wt-top {                   /* fittings on top */
   position: relative;
   height: 16px;
}
.wt-cap {                   /* round inspection lid, ribbed screw cap */
   position: absolute;
   bottom: -3px;
   left: 14%;
   width: 28%;
   height: 13px;
   border-radius: 5px 5px 0 0;
   background: repeating-linear-gradient(to right, var(--light2) 0 4px, #8a8a8a 4px 6px);
}
.wt-filler {                /* filler neck */
   position: absolute;
   bottom: -3px;
   right: 12%;
   width: 9%;
   height: 16px;
   border-radius: 3px 3px 0 0;
   background: var(--light2);
}
.wt-filler::before {        /* its flange */
   content: '';
   position: absolute;
   top: 0;
   left: -20%;
   right: -20%;
   height: 4px;
   border-radius: 2px;
   background: var(--light2);
}
.wt-vent {                  /* vent */
   position: absolute;
   bottom: -3px;
   right: 28%;
   width: 3%;
   height: 9px;
   border-radius: 2px 2px 0 0;
   background: var(--light2);
}
.wt-body {
   position: relative;
   aspect-ratio: 2.2;
   box-sizing: border-box;
   border: 3px solid var(--light2);
   border-radius: 14px;
   overflow: hidden;
   background: #ffffff12;
   box-shadow: inset 6px 0 10px #00000030, inset -6px 0 10px #00000030;   /* rounded plastic body */
}
.wt-fill {
   position: absolute;
   left: 0;
   right: 0;
   bottom: 0;
   max-height: 100%;
   box-sizing: border-box;
   background: linear-gradient(to bottom, #ffffff30, #00000050),     /* depth */
               var(--wt-color, #8a8a70);                               /* parameter 'farbe' */
   border-top: 2px solid color-mix(in srgb, var(--wt-color, #8a8a70), white 55%);   /* the surface of the water */
   transition: height 0.6s;
}
.wt-fill.full {
   background: linear-gradient(to bottom, #ffffff30, #00000050), #d04a2a;
   border-top-color: #ffc0a0;
}
.wt-scale {                 /* marks at 25 / 50 / 75 % on the right */
   position: absolute;
   inset: 0;
   background: repeating-linear-gradient(to top, transparent 0 calc(25% - 1px), #ffffff60 calc(25% - 1px) 25%);
   -webkit-mask: linear-gradient(to right, transparent 0 92%, black 92%);
   mask: linear-gradient(to right, transparent 0 92%, black 92%);
}
.wt-drain {                 /* drain below the tank: pipe with a ball valve */
   position: relative;
   height: 22px;
}
.wt-pipe {
   position: absolute;
   left: 16%;
   width: 6%;
   top: -3px;
   bottom: 0;
   background: var(--light2);
}
.wt-valve {                 /* brass body of the ball valve */
   position: absolute;
   left: calc(16% - 3%);
   width: 12%;
   top: 6px;
   height: 10px;
   border-radius: 3px;
   background: linear-gradient(to bottom, #e0c070, #b08830);
}
.wt-lever {                 /* red lever, beside the pipe (closed) */
   position: absolute;
   left: calc(16% + 9%);
   width: 15%;
   top: 8px;
   height: 5px;
   border-radius: 3px;
   background: #c83030;
}

.wt-stand {
   font-size: 0.75em;
   opacity: 0.6;
   text-align: center;
}

/* Designed in em (1em = 16px = natural size 22 x 27.8 em), grows with the widget (aspect ratio kept),
   but never gets smaller than the natural size. .avr-box is the size container (see the Samsung remote). */

.avr-box {
   container-type: size;
   width: 100%;
   height: 100%;
   min-height: 446px;
   display: flex;
   align-items: center;
   justify-content: center;
}
.avr {
   --avr-key: #2c2d30;
   --avr-key-hi: #3a3b3f;
   --avr-lcd: #bfeaff;
   font-size: 16px;
   font-size: max(16px, min(calc(100cqw / 22), calc(100cqh / 27.8)));
   flex: none;
   width: 22em;
   height: 27.8em;
   padding: 0.9em;
   box-sizing: border-box;
   display: flex;
   flex-direction: column;
   gap: 0.7em;
   border-radius: 1.2em;
   background: linear-gradient(180deg, #34363a 0%, #1f2023 6%, #17181a 100%);
   box-shadow: inset 0 0.0625em 0 #ffffff14, 0 0.25em 0.875em #0008;
   color: #d8d8d8;
   user-select: none;
}
.avr button {
   border: 0;
   padding: 0;
   font: inherit;
   color: inherit;
   background: var(--avr-key);
   cursor: pointer;
   -webkit-tap-highlight-color: transparent;
}
.avr button:active {
   filter: brightness(1.6);
}
.avr .mdi {
   font-size: 1.3em;
   line-height: 1;
}
.avr-head {
   flex: none;
   height: 2.2em;
   display: flex;
   align-items: center;
   justify-content: space-between;
}
.avr-title {
   font-weight: bold;
   font-size: 1.05em;
   letter-spacing: 0.08em;
   opacity: 0.85;
}
.avr-power, .avr-z2power {
   width: 2.2em;
   height: 2.2em;
   border-radius: 50%;
}
.avr-power, .avr-z2power.off { color: #e53935; }
.avr.on .avr-power, .avr-z2power.on { color: #4caf50; box-shadow: 0 0 0.5em #4caf5066; }
.avr-display {
   flex: none;
   height: 4.2em;
   box-sizing: border-box;
   padding: 0.5em 0.8em;
   border-radius: 0.6em;
   background: #07090b;
   box-shadow: inset 0 0.0625em 0.25em #000, 0 0 0 0.0625em #ffffff10;
   display: grid;
   grid-template-columns: 1fr auto;
   align-items: center;
   gap: 0.5em;
   color: var(--avr-lcd);
   text-shadow: 0 0 0.4em #5fc8ff66;
}
.avr-lcd-left {
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 0.15em;
}
.avr-source {
   font-size: 1.5em;
   line-height: 1.2;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-surround {
   font-size: 0.8em;
   opacity: 0.65;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-lcd-right {
   white-space: nowrap;
   text-align: right;
}
.avr-vol {
   font-size: 2em;
   line-height: 1;
}
.avr-unit {
   font-size: 0.8em;
   margin-left: 0.2em;
   opacity: 0.65;
}
.avr-mute {
   display: none;
   margin-right: 0.3em;
   color: #ff6b6b;
}
.avr-display.muted .avr-mute { display: inline; }
.avr-display.muted .avr-vol  { opacity: 0.4; }
.avr-vrow, .avr-z2vol {
   flex: none;
   height: 2.6em;
   display: flex;
   gap: 0.5em;
}
.avr-z2vol { height: 2em; }
.avr-vrow button, .avr-z2vol button {
   flex: 1;
   border-radius: 1.3em;
}
.avr-z2vol button { border-radius: 1em; }
.avr-mutebtn.muted { color: #e53935; }
.avr-srcs {
   flex: none;
   height: 4.8em;
   display: grid;
   grid-template-columns: repeat(4, 1fr);
   grid-template-rows: repeat(2, 2.2em);
   gap: 0.4em;
}
.avr-src {
   min-width: 0;
   padding: 0 0.3em !important;
   border-radius: 0.5em;
   font-size: 0.75em !important;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-src.aktiv {
   background: #1d4a63 !important;
   color: #fff;
   box-shadow: 0 0 0 0.15em #4fc3f7;
}
.avr-z2 {
   flex: none;
   height: 9.4em;
   display: flex;
   flex-direction: column;
   gap: 0.5em;
}
.avr-z2head {
   flex: none;
   height: 2.2em;
   display: flex;
   align-items: center;
   gap: 0.6em;
}
.avr-z2title {
   font-weight: bold;
   font-size: 0.9em;
   letter-spacing: 0.08em;
   opacity: 0.85;
}
.avr-z2info {
   flex: 1;
   min-width: 0;
   font-size: 0.75em;
   opacity: 0.8;
   white-space: nowrap;
   overflow: hidden;
   text-overflow: ellipsis;
}
.avr-z2power { width: 2em; height: 2em; }
.avr-z2srcs {
   height: 4.2em;
   grid-template-rows: repeat(2, 1.9em);
}
.avr-z2srcs .avr-src { font-size: 0.7em !important; }

.gb {
   display: flex;
   flex-direction: column;
   height: 100%;
   padding: 6px 10px;
   box-sizing: border-box;
   gap: 4px;
}
.gb-head {
   display: flex;
   align-items: center;
   gap: 6px;
   font-weight: bold;
}
.gb-pct {
   margin-left: auto;
   font-size: 0.85em;
   padding: 1px 8px;
   border-radius: 10px;
   background: var(--green);
   color: black;
}
.gb-pct.low {
   background: var(--red);
   color: white;
}
.gb-main {
   flex: 1;
   min-height: 0;
   display: flex;
   align-items: center;
   justify-content: center;
}

/* the bottle, grey steel like the German 11 kg bottle */

.gb-bottle {
   height: 100%;
   max-height: 230px;
   aspect-ratio: 0.5;
   display: flex;
   flex-direction: column;
   align-items: center;
   cursor: pointer;
}
.gb-collar {                /* protective collar with the grip hole, the valve inside */
   position: relative;
   width: 70%;
   height: 17%;
   box-sizing: border-box;
   border: 3px solid #9aa0a6;
   border-bottom: 0;
   border-radius: 10px 10px 0 0;
   background: #9aa0a630;
}
.gb-grip {
   position: absolute;
   left: 22%;
   right: 22%;
   top: 18%;
   height: 34%;
   border-radius: 50%;
   border: 2px solid #9aa0a6;
   background: #00000060;
}
.gb-valve {
   position: absolute;
   left: 41%;
   right: 41%;
   bottom: 0;
   height: 32%;
   border-radius: 2px 2px 0 0;
   background: #c8a040;     /* brass */
}
.gb-body {
   position: relative;
   flex: 1;
   width: 100%;
   box-sizing: border-box;
   border: 3px solid #9aa0a6;
   border-radius: 50% 50% 14% 14% / 18% 18% 5% 5%;
   overflow: hidden;
   background: #ffffff10;
}
.gb-fill {
   position: absolute;
   left: 0;
   right: 0;
   bottom: 0;
   max-height: 100%;
   background: linear-gradient(to right, #00000060, #ffffff70 38%, #00000018 70%, #00000070),   /* shine of the round body */
               var(--gb-color, #9aa0a6);                                                      /* parameter 'farbe' */
   transition: height 0.6s;
}
.gb-fill.low {
   background: linear-gradient(to right, #00000060, #ffffff70 38%, #00000018 70%, #00000070), #c83030;
}
.gb-seam {                  /* weld seam around the middle */
   position: absolute;
   left: 0;
   right: 0;
   top: 52%;
   height: 2px;
   background: #00000040;
   box-shadow: 0 1px 0 #ffffff30;
}
.gb-scale {                 /* marks at 25 / 50 / 75 % on the right */
   position: absolute;
   inset: 0;
   background: repeating-linear-gradient(to top, transparent 0 calc(25% - 1px), #ffffff50 calc(25% - 1px) 25%);
   -webkit-mask: linear-gradient(to right, transparent 0 78%, black 78%);
   mask: linear-gradient(to right, transparent 0 78%, black 78%);
}
.gb-foot {                  /* foot ring */
   width: 86%;
   height: 6%;
   box-sizing: border-box;
   border: 3px solid #9aa0a6;
   border-top: 0;
   border-radius: 0 0 4px 4px;
   background: #9aa0a630;
}
/* bottom row: temperature, state, battery and quality of the sensor */

.gb-foot-row {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 8px;
}
.gb-temp {
   font-size: 0.85em;
   opacity: 0.8;
   cursor: pointer;
}
.gb-temp .mdi {
   color: var(--red);
}
.gb-stand {
   font-size: 0.75em;
   opacity: 0.6;
   text-align: center;
}
.gb-icons {
   display: flex;
   gap: 4px;
   font-size: 1.2em;
}
.gb-icons .mdi {
   cursor: pointer;
}

/* battery like the sensor setup: green, yellow < 60 %, orange < 30 %, red < 15 % */

.gb-batt        { color: var(--green); }
.gb-batt.gb-b60 { color: var(--yellow); }
.gb-batt.gb-b30 { color: var(--orange); }
.gb-batt.gb-b15 { color: var(--red); }

/* quality of the measurement 0-3: green 3, orange 2, red below */

.gb-qual        { color: var(--green); }
.gb-qual.gb-q2  { color: var(--orange); }
.gb-qual.gb-q1  { color: var(--red); }

.gb-hide {
   display: none;
}

.pb {
   display: flex;
   flex-direction: column;
   height: 100%;
   padding: 6px 10px;
   box-sizing: border-box;
   gap: 4px;
}
.pb-head {
   display: flex;
   align-items: center;
   gap: 6px;
   font-weight: bold;
}
.pb-head .mdi {
   color: #c08a4a;
}
.pb-pct {
   margin-left: auto;
   font-size: 0.85em;
   padding: 1px 8px;
   border-radius: 10px;
   background: var(--green);
   color: black;
}
.pb-pct.low {
   background: var(--red);
   color: white;
}
.pb-main {
   flex: 1;
   min-height: 0;
   container-type: size;      /* the unit takes the height of the widget, limited by its width */
   display: flex;
   align-items: center;
   justify-content: center;
}

/* the unit: height by the widget, the body keeps its aspect ratio */

.pb-unit {
   position: relative;
   width: min(100% - 40px, 200px, (100cqh - 58px) * 0.8);
   display: flex;
   flex-direction: column;
   cursor: pointer;
}

/* on top: cyclone of the suction system with its two hoses */

.pb-top {
   position: relative;
   height: 26px;
}
.pb-cyclone {
   position: absolute;
   bottom: 0;
   left: 30%;
   width: 24%;
   height: 24px;
   box-sizing: border-box;
   border: 2px solid #b8bcc0;
   border-radius: 5px 5px 0 0;
   background: linear-gradient(to right, #9aa0a6, #e8ecef 40%, #a8aeb4);
}
.pb-cyclone.pb-on {             /* suction turbine running */
   border-color: var(--green);
   box-shadow: 0 0 6px var(--green);
}
.pb-hose {                      /* hoses to the store room, bent to the right */
   position: absolute;
   left: 54%;
   box-sizing: border-box;
   border: 4px solid #6a6e72;
   border-left: 0;
   border-bottom: 0;
   border-radius: 0 14px 0 0;
}
.pb-hose1 {
   top: 4px;
   width: 40%;
   height: 30px;
}
.pb-hose2 {
   top: 12px;
   width: 30%;
   height: 22px;
}

/* lid and casing (light, red stripe) */

.pb-lid {
   position: relative;
   z-index: 1;
   width: 104%;
   margin-left: -2%;
   height: 9px;
   border-radius: 4px 4px 1px 1px;
   background: linear-gradient(to bottom, #f2f2f2, #c8c8c8);
}
.pb-body {
   position: relative;
   aspect-ratio: 0.8;
   box-sizing: border-box;
   padding: 12% 9% 7% 9%;
   border-radius: 0 0 4px 4px;
   background: linear-gradient(to right, #c4c4c4, #ececec 30%, #e2e2e2 75%, #b8b8b8);
}
.pb-stripe {
   position: absolute;
   top: 4%;
   left: 0;
   right: 0;
   height: 4%;
   background: #c8102e;
}

/* chamber with the funnel at the bottom (clip-path), the pellets inside */

.pb-chamber {
   position: relative;
   height: 100%;
   overflow: hidden;
   background: #2a2a2a;
   clip-path: polygon(0 0, 100% 0, 100% 72%, 62% 100%, 38% 100%, 0 72%);
   box-shadow: inset 0 4px 8px #00000080;
}
.pb-fill {
   position: absolute;
   left: 0;
   right: 0;
   bottom: 0;
   max-height: 100%;
   background:                                    /* pellets: dark and light grains on the base color */
      radial-gradient(ellipse 2px 1.4px at 30% 40%, #00000055 98%, transparent) 0 0 / 7px 5px,
      radial-gradient(ellipse 1.6px 1.2px at 70% 70%, #ffffff40 98%, transparent) 0 0 / 6px 6px,
      radial-gradient(ellipse 1.8px 1.2px at 50% 20%, #00000035 98%, transparent) 3px 2px / 9px 7px,
      var(--pb-color, #b07a3c);                  /* parameter 'farbe' */
   border-top: 2px solid #ffffff30;
   box-sizing: border-box;
   transition: height 0.6s;
}
.pb-fill.low {
   background:
      radial-gradient(ellipse 2px 1.4px at 30% 40%, #00000055 98%, transparent) 0 0 / 7px 5px,
      radial-gradient(ellipse 1.6px 1.2px at 70% 70%, #ffffff40 98%, transparent) 0 0 / 6px 6px,
      #b03020;
}
.pb-scale {                     /* marks at 25 / 50 / 75 % on the right */
   position: absolute;
   inset: 0;
   background: repeating-linear-gradient(to top, transparent 0 calc(25% - 1px), #ffffff60 calc(25% - 1px) 25%);
   -webkit-mask: linear-gradient(to right, transparent 0 88%, black 88%);
   mask: linear-gradient(to right, transparent 0 88%, black 88%);
}

/* below: feed screw to the boiler (right) and the feet */

.pb-bottom {
   position: relative;
   height: 16px;
}
.pb-screw {
   position: absolute;
   top: 0;
   left: 42%;
   right: -16px;
   height: 9px;
   border-radius: 0 3px 3px 0;
   background: linear-gradient(to bottom, #8a8e92, #5a5e62);
}
.pb-foot {
   position: absolute;
   top: 0;
   width: 10%;
   height: 100%;
   background: #5a5e62;
   border-radius: 0 0 2px 2px;
}
.pb-foot1 { left: 6%; }
.pb-foot2 { right: 6%; }

/* bottom row: suction turbine, state */

.pb-foot-row {
   display: flex;
   align-items: center;
   justify-content: center;
   gap: 12px;
}
.pb-saug {
   font-size: 0.85em;
   opacity: 0.6;
   cursor: pointer;
}
.pb-saug.pb-on {
   opacity: 1;
   color: var(--green);
}
.pb-stand {
   font-size: 0.75em;
   opacity: 0.6;
}
.pb-hide {
   display: none;
}

.rk {
   display: flex;
   flex-direction: column;
   justify-content: space-between;
   height: 100%;
   padding: 6px 10px;
   box-sizing: border-box;
}
.rk-raum {
   font-weight: bold;
   color: var(--light2);
}
.rk-temp {
   text-align: center;
   font-size: 1.4em;
}
.rk-temp .mdi {
   color: var(--red);
}
.rk-wert {
   font-size: 2em;
   font-weight: bold;
}
.rk-unit {
   margin-left: 2px;
   opacity: 0.7;
}
.rk-row {
   display: flex;
   justify-content: space-around;
   font-size: 1.1em;
}
.rk-row .mdi {
   color: var(--green);
}
.rk-foot {
   display: flex;
   justify-content: space-between;
   font-size: 0.75em;
   opacity: 0.6;
}
.rk-foot .alt {
   color: var(--red);
}

.tp {
   container-type: size;   /* for the compact layout of a low widget (@container below) */
   display: flex;
   flex-direction: column;
   height: 100%;
   padding: 6px 8px;
   box-sizing: border-box;
   gap: 4px;
}
.tp-head {
   display: flex;
   align-items: center;
   gap: 6px;
   font-weight: bold;
}
.tp-status {
   margin-left: auto;
   font-size: 0.8em;
   padding: 1px 8px;
   border-radius: 10px;
   background: var(--green);
   color: black;
}
.tp-status.alarm {
   background: red;
   color: white;
}
.tp-car {
   position: relative;
   flex: 1;
   display: grid;
   grid-template-rows: auto 1fr auto auto;
   row-gap: 6px;
   padding: 14% 0 6% 0;
}
.tp-body {
   position: absolute;
   top: 2%;
   bottom: 2%;
   left: 50%;
   width: 76px;
   transform: translateX(-50%);
   border: 2px solid var(--light2);
   border-radius: 22px 22px 6px 6px;
   background: #ffffff10;
}
.tp-cab {
   margin: 14px 8px 0 8px;
   height: 12px;
   border: 2px solid var(--light2);
   border-bottom: 0;
   border-radius: 10px 10px 0 0;
   opacity: 0.6;
}
.tp-dir {
   position: absolute;
   top: 0;
   left: 50%;
   transform: translate(-50%, -60%);
   opacity: 0.5;
}
.tp-axle {
   position: relative;
   display: grid;
   grid-template-columns: 1fr 14px 56px 14px 1fr;
   align-items: center;
}
.tp-axlebar {
   height: 3px;
   background: var(--light2);
   opacity: 0.5;
}
.tp-tire {
   height: 30px;
   border-radius: 4px;
   background: var(--green);
}
.tp-tire.low   { background: red; }
.tp-tire.high  { background: orange; }
.tp-tire.stale { background: #777; }
.tp-val {
   font-size: 0.85em;
   line-height: 1.15;
}
.tp-val b {
   font-size: 1.3em;
}
.tp-val small {
   opacity: 0.7;
}
.tp-left {
   text-align: right;
   padding-right: 6px;
}
.tp-right {
   text-align: left;
   padding-left: 6px;
}
.tp-val.low  { color: red; }
.tp-val.high { color: orange; }
/* battery like the sensor setup (batterySymbol()): symbol by the charge in steps of 10 %,
   green, yellow < 60 %, orange < 30 %, red < 15 % */

.tp-batt      { color: var(--green); font-size: larger; }
.tp-batt.tp-b60 { color: var(--yellow); }
.tp-batt.tp-b30 { color: var(--orange); }
.tp-batt.tp-b15 { color: var(--red); }
.tp-soll {
   align-self: center;
   justify-self: center;
   max-width: 70px;        /* inside the body (76px) */
   font-size: 0.7em;
   line-height: 1.25;
   opacity: 0.6;
   text-align: center;
}
.tp-foot {
   font-size: 0.75em;
   opacity: 0.6;
   text-align: center;
}

.tp-hide {
  display: none;
}

.tp-val.stale {
  color: #777;
}

.tp-nowrap {
  white-space: nowrap;
}

.tp-stand {
  margin-top: 0.8em;
}

/* low widget (e.g. iPhone, smaller widget base height): smaller tires, fonts and gaps, no scrolling */

@container (max-height: 300px) {
  .tp           { padding: 2px 6px; gap: 2px; }
  .tp-head      { font-size: 0.9em; }
  .tp-car       { row-gap: 2px; padding: 8% 0 2% 0; }
  .tp-tire      { height: 20px; }
  .tp-val       { font-size: 0.75em; line-height: 1.05; }
  .tp-val b     { font-size: 1.2em; }
  .tp-soll      { font-size: 0.65em; line-height: 1.1; }
  .tp-stand     { margin-top: 0.3em; }
  .tp-cab       { margin-top: 8px; height: 8px; }
}

/* a cap assigned but no data (invalid, e.g. unscrewed / empty battery): red; a wheel without cap
   (TPMS:0x0, no sensor) stays gray */

.tp-tire.nodata { background: red; }
.tp-val.nodata  { color: red; }

/* no current value (cap invalid or no cap): hide pressure / temperature / battery, show a dash */

.tp-none          { display: none; }
.tp-val.stale .tp-v    { display: none; }
.tp-val.stale .tp-none { display: inline; font-size: 1.3em; }

/* disturbed tire (pressure too low / too high, cap without data): red warning triangle,
   not for a wheel without cap (stale without nodata) */

.tp-warn { display: none; color: red; margin: 0 3px; font-size: 2em; line-height: 1; }

/* icon vertically centered to the tire, with and without the values (pressure / temperature / battery) */

.tp-val       { display: flex; align-items: center; }
.tp-val.tp-left  { justify-content: flex-end; }
.tp-val.tp-right { justify-content: flex-start; }
.tp-val.low .tp-warn, .tp-val.high .tp-warn, .tp-val.nodata .tp-warn { display: inline; }
.tp-val.stale:not(.nodata) .tp-warn { display: none; }



/* known cap without data: only the warning triangle, no dash */

.tp-val.nodata .tp-none { display: none; }

/* The remote is designed in em (1em = 16px = natural size 10.6 x 30 em) and grows with the
   widget (aspect ratio kept), but never gets smaller than the natural size (scrolls then).
   .fb-box is the size container: font-size of .fb = the em, min() of the fit by width / height. */

.fb-box {
   container-type: size;
   width: 100%;
   height: 100%;
   min-height: 480px;
   display: flex;
   align-items: center;
   justify-content: center;
}
.fb {
   --fb-body: #1d1e20;
   --fb-key: #2c2d30;
   --fb-key-hi: #3a3b3f;
   --fb-text: #d8d8d8;
   font-size: 16px;
   font-size: max(16px, min(calc(100cqw / 10.625), calc(100cqh / 30)));
   flex: none;
   width: 10.625em;
   padding: 0.875em 0.75em 1em;
   box-sizing: border-box;
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 0.875em;
   border-radius: 2.125em;
   background: linear-gradient(180deg, #2a2b2e 0%, var(--fb-body) 18%, var(--fb-body) 100%);
   box-shadow: inset 0 0.0625em 0 #ffffff14, 0 0.25em 0.875em #0008;
   color: var(--fb-text);
   user-select: none;
}
.fb button {
   border: 0;
   padding: 0;
   font: inherit;
   color: inherit;
   cursor: pointer;
   -webkit-tap-highlight-color: transparent;
}
.fb button:active {
   filter: brightness(1.6);
   transform: scale(0.94);
}
.fb .mdi {
   font-size: 1.3em;
   line-height: 1;
}
.fb-top {
   width: 100%;
   display: flex;
   align-items: center;
   justify-content: space-between;
   padding: 0 0.375em;
   box-sizing: border-box;
}
.fb-power {
   width: 2.125em;
   height: 2.125em;
   border-radius: 50%;
   background: var(--fb-key);
}
.fb.on .fb-power {
   color: #4caf50;
   box-shadow: 0 0 0.5em #4caf5066;
}
.fb.off .fb-power {
   color: #e53935;
}
.fb-mic {
   width: 0.3125em;
   height: 0.3125em;
   border-radius: 50%;
   background: #000;
   box-shadow: 0 0 0 0.125em #333;
}
.fb-btn {
   width: 2.375em;
   height: 2.375em;
   border-radius: 50%;
   background: var(--fb-key);
}
.fb-small {
   width: 1.875em;
   height: 1.875em;
}
.fb-small .mdi {
   font-size: 1.05em;
}
.fb-dpad {
   position: relative;
   width: 8em;
   height: 8em;
   border-radius: 50%;
   background: radial-gradient(circle, var(--fb-key-hi) 0%, var(--fb-key) 70%);
   box-shadow: inset 0 0 0 0.0625em #ffffff10, 0 0.125em 0.25em #0006;
}
.fb-dir {
   position: absolute;
   width: 2.5em;
   height: 2.5em;
   background: transparent;
   border-radius: 50%;
}
.fb-dir .mdi {
   font-size: 1.5em;
   opacity: 0.75;
}
.fb-up    { top: 0.125em;    left: 2.75em; }
.fb-down  { bottom: 0.125em; left: 2.75em; }
.fb-left  { left: 0.125em;   top: 2.75em; }
.fb-right { right: 0.125em;  top: 2.75em; }
.fb-ok {
   position: absolute;
   left: 2.25em;
   top: 2.25em;
   width: 3.5em;
   height: 3.5em;
   border-radius: 50%;
   background: var(--fb-body);
   box-shadow: inset 0 0.0625em 0.125em #000a, 0 0 0 0.0625em #ffffff12;
}
.fb-row {
   display: flex;
   align-items: center;
   gap: 0.625em;
}
.fb-pp {
   display: flex;
   border-radius: 1.1875em;
   overflow: hidden;
   background: var(--fb-key);
}
.fb-pp button {
   width: 1.625em;
   height: 2.375em;
   background: transparent;
}
.fb-pp button + button {
   border-left: 0.0625em solid #ffffff12;
}
.fb-pp .mdi {
   font-size: 1.05em;
}
.fb-rockers {
   display: flex;
   gap: 1em;
}
.fb-rocker {
   display: flex;
   flex-direction: column;
   width: 2.75em;
   border-radius: 1.375em;
   overflow: hidden;
   background: var(--fb-key);
   box-shadow: 0 0.125em 0.25em #0006;
}
.fb-rocker button {
   height: 2.375em;
   background: transparent;
}
.fb-rocker .fb-label {
   height: 2.125em;
   display: flex;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   gap: 0.0625em;
   font-size: 0.75em;
   letter-spacing: 0.0625em;
   opacity: 0.8;
}
.fb-rocker .fb-label .mdi {
   font-size: 1.15em;
}
.fb-rocker .fb-label.muted {
   color: #e53935;
   opacity: 1;
}
.fb-vol {
   font-size: 0.9em;
}
.fb-apps {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 0.375em;
   width: 100%;
}
.fb-app {
   height: 1.5em;
   border-radius: 0.375em;
   font-size: 0.72em !important;
   font-weight: bold;
   white-space: nowrap;
   overflow: hidden;
   opacity: 0.85;
}
.fb-app .mdi {
   font-size: 1.1em;
   vertical-align: middle;
}
.fb-app.aktiv {
   opacity: 1;
   box-shadow: 0 0 0 0.125em #fff;
}
.fb-netflix { background: #141414; color: #e50914 !important; letter-spacing: 0.0625em; }
.fb-prime   { background: #00a8e1; color: #fff !important; }
.fb-youtube { background: #fff; color: #222 !important; }
.fb-youtube .mdi { color: #ff0000; }
.fb-disney  { background: #0e1a5c; color: #fff !important; }
.fb-name {
   font-size: 0.7em;
   line-height: 1.2;
   letter-spacing: 0.125em;
   text-transform: uppercase;
   opacity: 0.45;
}

.wt {
   display: flex;
   flex-direction: column;
   height: 100%;
   padding: 6px 10px;
   box-sizing: border-box;
   gap: 4px;
}
.wt-head {
   display: flex;
   align-items: center;
   gap: 6px;
   font-weight: bold;
}
.wt-head .mdi {
   color: #3b9be8;
}
.wt-pct {
   margin-left: auto;
   font-size: 0.85em;
   padding: 1px 8px;
   border-radius: 10px;
   background: #3b9be8;
   color: white;
}
.wt-pct.low {
   background: var(--red);
}
.wt-main {
   flex: 1;
   min-height: 0;
   container-type: size;      /* the tank takes the width of the widget, limited by its height */
   display: flex;
   align-items: center;
   justify-content: center;
}

/* the tank: wide and flat, its height by the width (aspect-ratio of the body) */

.wt-tank {
   position: relative;
   width: min(100% - 16px, 340px, (100cqh - 22px) * 2.2);
   display: flex;
   flex-direction: column;
   cursor: pointer;
}
.wt-top {                   /* fittings on top */
   position: relative;
   height: 16px;
}
.wt-cap {                   /* round inspection lid, ribbed screw cap */
   position: absolute;
   bottom: -3px;
   left: 14%;
   width: 28%;
   height: 13px;
   border-radius: 5px 5px 0 0;
   background: repeating-linear-gradient(to right, var(--light2) 0 4px, #8a8a8a 4px 6px);
}
.wt-filler {                /* filler neck */
   position: absolute;
   bottom: -3px;
   right: 12%;
   width: 9%;
   height: 16px;
   border-radius: 3px 3px 0 0;
   background: var(--light2);
}
.wt-filler::before {        /* its flange */
   content: '';
   position: absolute;
   top: 0;
   left: -20%;
   right: -20%;
   height: 4px;
   border-radius: 2px;
   background: var(--light2);
}
.wt-vent {                  /* vent */
   position: absolute;
   bottom: -3px;
   right: 28%;
   width: 3%;
   height: 9px;
   border-radius: 2px 2px 0 0;
   background: var(--light2);
}
.wt-body {
   position: relative;
   aspect-ratio: 2.2;
   box-sizing: border-box;
   border: 3px solid var(--light2);
   border-radius: 14px;
   overflow: hidden;
   background: #ffffff12;
   box-shadow: inset 6px 0 10px #00000030, inset -6px 0 10px #00000030;   /* rounded plastic body */
}
.wt-fill {
   position: absolute;
   left: 0;
   right: 0;
   bottom: 0;
   max-height: 100%;
   box-sizing: border-box;
   background: linear-gradient(to bottom, #ffffff30, #00000050),     /* depth */
               var(--wt-color, #3b8fd8);                               /* parameter 'farbe' */
   border-top: 2px solid color-mix(in srgb, var(--wt-color, #3b8fd8), white 55%);   /* the surface of the water */
   transition: height 0.6s;
}
.wt-fill.low {
   background: linear-gradient(to bottom, #ffffff30, #00000050), #d04a2a;
   border-top-color: #ffc0a0;
}
.wt-scale {                 /* marks at 25 / 50 / 75 % on the right */
   position: absolute;
   inset: 0;
   background: repeating-linear-gradient(to top, transparent 0 calc(25% - 1px), #ffffff60 calc(25% - 1px) 25%);
   -webkit-mask: linear-gradient(to right, transparent 0 92%, black 92%);
   mask: linear-gradient(to right, transparent 0 92%, black 92%);
}
.wt-outlet {                /* drain at the side, bottom */
   position: absolute;
   left: -9px;
   bottom: 10%;
   width: 10px;
   height: 9px;
   border-radius: 2px 0 0 2px;
   background: var(--light2);
}

.wt-stand {
   font-size: 0.75em;
   opacity: 0.6;
   text-align: center;
}
